#!/usr/bin/env python3
"""
Applies the "start-screen dialog + working submit-name field" patch
to every PreLoG-style quiz HTML file in a folder.

Each file must be untouched (i.e. still have the old top name-bar and
the old submit-confirm modal) for the patch to apply. Files that were
already patched, or whose structure differs, are skipped and reported.

Usage:
    python3 apply_patch.py /path/to/folder/with/html/files
    python3 apply_patch.py file1.html file2.html ...
"""
